static bool Equal(const void* a,const void* b,unsigned int n){const unsigned char* p=(const unsigned char*)a,*q=(const unsigned char*)b;for(unsigned int i=0;i<n;i++)if(p[i]!=q[i])return false;return true;}
static PrefabScene::Property* Prop(PrefabScene::Model& model,PrefabScene::Node& node,const char* name,const char* data){PrefabScene::Property* p=(PrefabScene::Property*)model.memory.Allocate(sizeof(PrefabScene::Property));if(!p)return 0;lstrcpyA(p->name,name);lstrcpyA(p->type,"string");p->string=true;p->data=const_cast<char*>(data);if(!node.properties)node.properties=p;else{PrefabScene::Property* last=node.properties;while(last->next)last=last->next;last->next=p;}return p;}
static bool Empty(const NativeRawNavMesh::Builder& b){return !b.data&&!b.size&&b.sourceNode==NativeRawNavMesh::Missing&&b.brushNode==NativeRawNavMesh::Missing&&b.generatedLong.sourceNode==NativeRawNavMesh::Missing&&!b.generatedLong.property&&!b.generatedLong.value;}
static bool Rejected(NativeRawNavMesh::Builder& b,const PrefabScene::Model& m,const WorldText::Vec3& o,const NativeRawNavMesh::Settings& s,unsigned int node=0xffffffffu){return !b.Build(m,o,s)&&Empty(b)&&b.error&&b.error[0]&&b.errorNode==node;}
// These are boundaries of the proved finite profile, not universal rejection
// rules. The general source path has separate original-oracle regression tests.
static bool ProfileRejected(NativeRawNavMesh::Builder& b,const PrefabScene::Model& m,const WorldText::Vec3& o,const NativeRawNavMesh::Settings& s,unsigned int node){return !b.BuildProfile(m,o,s)&&Empty(b)&&b.error&&b.error[0]&&b.errorNode==node;}
// A childless AIRegion or AINavMeshLink* is omitted by the original without
// changing raw (sp-oracle/omission-rules: aux-region-no-hull, aux-link-no-child):
// the general route must equal its own result with that node made neutral.
static bool Omitted(NativeRawNavMesh::Builder& b,const PrefabScene::Model& m,const WorldText::Vec3& o,const NativeRawNavMesh::Settings& s,PrefabScene::Node& node){
 if(!b.Build(m,o,s)||!b.generalProfile||b.generalRealCount)return false;unsigned int kind=node.kind;node.kind=0;NativeRawNavMeshGeneral::Builder neutral;
 bool same=neutral.Build(m,o)&&neutral.size==b.size&&Equal(neutral.data,b.data,b.size)&&!neutral.linkCount&&!neutral.regionCount;node.kind=kind;return same;}
static bool Put(HANDLE f,const void* p,unsigned int n){DWORD done=0;return WriteFile(f,p,n,&done,0)&&done==n;}
static float Bits(unsigned int n){float f;memcpy(&f,&n,4);return f;}
